CREATE TABLE IF NOT EXISTS world_news (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), event_id UUID REFERENCES world_event_instances(id), headline TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL, importance INTEGER NOT NULL DEFAULT 1 CHECK(importance BETWEEN 1 AND 5), location_id TEXT, published_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(event_id)); CREATE INDEX IF NOT EXISTS idx_world_news_time ON world_news(published_at DESC); CREATE INDEX IF NOT EXISTS idx_world_news_category ON world_news(category,published_at DESC);